pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(_tos.length > 0);
        vm.assume(v > 0);
        CallRecorder recorder = new CallRecorder();
        vm.prank(from);
        bool ok = c.transfer(from, address(recorder), _tos, v);
        assertTrue(ok);
        for (uint i = 0; i < _tos.length; i++) {
            assertEq(recorder.lastAmount(i), v);
        }
    }
}

contract CallRecorder {
    uint256[] public lastAmount;
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastAmount.push(amount);
        return true;
    }
}
